<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class InvoiceItem extends Model{protected $fillable=['invoice_session_id','product_id','description','unit','quantity','unit_price','line_total','sort_order'];protected function casts():array{return ['quantity'=>'decimal:4','unit_price'=>'decimal:2','line_total'=>'decimal:2'];}public function session(){return $this->belongsTo(InvoiceSession::class,'invoice_session_id');}}
